import{_ as s,o as e,c as l,ag as t}from"./chunks/framework.DB9Ll7VW.js";const h=JSON.parse('{"title":"Pro add-ons","description":"Every Sikshya Pro add-on with what it does, where you find it in the admin, and a direct link to upgrade. License plans gate Starter, Growth, and Scale tiers.","frontmatter":{"title":"Pro add-ons","description":"Every Sikshya Pro add-on with what it does, where you find it in the admin, and a direct link to upgrade. License plans gate Starter, Growth, and Scale tiers."},"headers":[],"relativePath":"third-party-integrations.md","filePath":"third-party-integrations.md","lastUpdated":1778327862000}'),r={name:"third-party-integrations.md"};function o(n,a,i,c,p,u){return e(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="pro-add-ons" tabindex="-1">Pro add-ons <a class="header-anchor" href="#pro-add-ons" aria-label="Permalink to &quot;Pro add-ons&quot;">​</a></h1><div class="doc-pro-callout"><span class="doc-pro-pill">Pro</span><span><strong>Every add-on on this page is Sikshya Pro.</strong> Each card below tells you the minimum plan tier (Starter, Growth, Scale). For a flat one-card-per-add-on view plus a tier matrix, see <a href="/addons">All add-ons</a>.</span><a class="doc-pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing" target="_blank" rel="noopener">View pricing →</a></div><p>Sikshya Pro is a separate plugin you install on top of the free Sikshya LMS. After activating your license under <span class="screen-path">Sikshya → License</span>, you toggle individual add-ons in <span class="screen-path">Sikshya → Add-ons</span>.</p><p>License plans control which add-ons you can turn on:</p><ul><li><strong>Starter</strong> — entry-level paid tier.</li><li><strong>Growth</strong> — most use cases.</li><li><strong>Scale</strong> — agency, enterprise, marketplace.</li></ul><p>Below is every add-on with what it does, where it lives in the admin, and an &quot;Upgrade&quot; link.</p><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Compare plans</span></div><p class="pro-callout__desc">All plans include free updates and priority support. Pick the plan that includes the add-ons you need — you can always upgrade later.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Compare Sikshya Pro plans →</a></div><h2 id="build-curriculum-assets" tabindex="-1">Build (curriculum &amp; assets) <a class="header-anchor" href="#build-curriculum-assets" aria-label="Permalink to &quot;Build (curriculum &amp; assets)&quot;">​</a></h2><h3 id="course-bundles" tabindex="-1">Course bundles <a class="header-anchor" href="#course-bundles" aria-label="Permalink to &quot;Course bundles&quot;">​</a></h3><p>Sell several courses for one bundled price (&quot;bootcamp pack&quot;). Buyers are auto-enrolled in every course in the bundle.</p><ul><li><strong>Where:</strong> <span class="screen-path">Sikshya → Course → Courses → New → Course type: Bundle</span> and <span class="screen-path">Commerce → Bundles</span>.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Course bundles</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock bundles →</a></div><h3 id="course-reviews-ratings" tabindex="-1">Course reviews &amp; ratings <a class="header-anchor" href="#course-reviews-ratings" aria-label="Permalink to &quot;Course reviews &amp; ratings&quot;">​</a></h3><p>Star ratings and written reviews on the course page, with admin moderation.</p><ul><li><strong>Where:</strong> <span class="screen-path">Sikshya → Course → Reviews</span> after enabling the add-on; per-course toggle in Course Builder → Course options.</li><li><strong>Plan:</strong> Starter.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Course reviews &amp; ratings</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock reviews →</a></div><h3 id="course-discussions-q-a" tabindex="-1">Course discussions &amp; Q&amp;A <a class="header-anchor" href="#course-discussions-q-a" aria-label="Permalink to &quot;Course discussions &amp; Q&amp;A&quot;">​</a></h3><p>In-course discussion threads and Q&amp;A panel with instructor moderation. Great for cohort programs.</p><ul><li><strong>Where:</strong> <span class="screen-path">Sikshya → Course → Discussions</span> after enabling.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Course discussions &amp; Q&amp;A</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock discussions →</a></div><h3 id="multi-instructor-co-authors" tabindex="-1">Multi-instructor &amp; co-authors <a class="header-anchor" href="#multi-instructor-co-authors" aria-label="Permalink to &quot;Multi-instructor &amp; co-authors&quot;">​</a></h3><p>Assign multiple instructors per course. Set roles (Owner / Editor / Grader). Split revenue per course.</p><ul><li><strong>Where:</strong> <span class="screen-path">Sikshya → Course → Course staff</span> + the <strong>Manage staff</strong> action on each course row.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Multi-instructor &amp; co-authors</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock multi-instructor →</a></div><h3 id="instructor-dashboard" tabindex="-1">Instructor dashboard <a class="header-anchor" href="#instructor-dashboard" aria-label="Permalink to &quot;Instructor dashboard&quot;">​</a></h3><p>A focused home page for instructors — their courses, their enrollments, their earnings — without exposing the full WordPress admin.</p><ul><li><strong>Where:</strong> appears for users with the Sikshya Instructor role after enabling.</li><li><strong>Plan:</strong> Starter.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Instructor dashboard</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock the instructor dashboard →</a></div><h3 id="live-classes-zoom-meet-classroom" tabindex="-1">Live classes (Zoom / Meet / Classroom) <a class="header-anchor" href="#live-classes-zoom-meet-classroom" aria-label="Permalink to &quot;Live classes (Zoom / Meet / Classroom)&quot;">​</a></h3><p>Pin a Zoom or Google Meet URL to a lesson so learners always click the right link. Instructors can rotate the URL without re-publishing the lesson.</p><ul><li><strong>Where:</strong> lesson type <strong>Live class</strong> appears in the curriculum tab; settings under <span class="screen-path">Integrations → Live classes</span>.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Live classes (Zoom / Meet)</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock live classes →</a></div><h3 id="scorm-h5p" tabindex="-1">SCORM / H5P <a class="header-anchor" href="#scorm-h5p" aria-label="Permalink to &quot;SCORM / H5P&quot;">​</a></h3><p>Embed packaged SCORM 1.2 / 2004 content or H5P interactives as a lesson. Tracks progress through the SCORM API.</p><ul><li><strong>Where:</strong> lesson types <strong>SCORM</strong> and <strong>H5P</strong> in the curriculum; settings under <span class="screen-path">Integrations → SCORM / H5P</span>.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">SCORM / H5P</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock SCORM / H5P →</a></div><h2 id="teach-assessment-automation-learner-journey" tabindex="-1">Teach (assessment, automation, learner journey) <a class="header-anchor" href="#teach-assessment-automation-learner-journey" aria-label="Permalink to &quot;Teach (assessment, automation, learner journey)&quot;">​</a></h2><h3 id="content-drip-scheduled-unlock" tabindex="-1">Content drip &amp; scheduled unlock <a class="header-anchor" href="#content-drip-scheduled-unlock" aria-label="Permalink to &quot;Content drip &amp; scheduled unlock&quot;">​</a></h3><p>Release lessons by date, X-days-from-enrollment, or cohort start. Replace &quot;complete-in-order&quot; with calendar-driven release.</p><ul><li><strong>Where:</strong> <span class="screen-path">Sikshya → Course → Learning rules → Scheduled access</span>.</li><li><strong>Plan:</strong> Starter.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Content drip</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock content drip →</a></div><h3 id="drip-automation-emails" tabindex="-1">Drip &amp; automation emails <a class="header-anchor" href="#drip-automation-emails" aria-label="Permalink to &quot;Drip &amp; automation emails&quot;">​</a></h3><p>&quot;Lesson unlocked&quot; / &quot;Course unlocked&quot; / weekly digest emails wired to drip rules.</p><ul><li><strong>Where:</strong> <span class="screen-path">Email → Templates</span> — three new drip templates appear.</li><li><strong>Plan:</strong> Starter.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Drip notifications</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock drip notifications →</a></div><h3 id="prerequisites-lessons-courses" tabindex="-1">Prerequisites (lessons &amp; courses) <a class="header-anchor" href="#prerequisites-lessons-courses" aria-label="Permalink to &quot;Prerequisites (lessons &amp; courses)&quot;">​</a></h3><p>Require completion of chosen lessons or whole courses before the next step unlocks.</p><ul><li><strong>Where:</strong> <span class="screen-path">Sikshya → Course → Learning rules → Prerequisites</span>.</li><li><strong>Plan:</strong> Starter.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Prerequisites</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock prerequisites →</a></div><h3 id="calendar" tabindex="-1">Calendar <a class="header-anchor" href="#calendar" aria-label="Permalink to &quot;Calendar&quot;">​</a></h3><p>Dated schedule on the learner&#39;s account — enrollments, drip unlocks, assignment due dates — with REST data for custom UIs.</p><ul><li><strong>Where:</strong> <span class="screen-path">Sikshya → Reports → Calendar</span>.</li><li><strong>Plan:</strong> Starter.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Calendar</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock calendar →</a></div><h3 id="advanced-assignments" tabindex="-1">Advanced assignments <a class="header-anchor" href="#advanced-assignments" aria-label="Permalink to &quot;Advanced assignments&quot;">​</a></h3><p>Rubric grading, restricted file types, resubmissions, and a grading queue with filters (ungraded, late, failed).</p><ul><li><strong>Where:</strong> Course Builder → Curriculum → assignment editor; queue under <span class="screen-path">Grading &amp; submissions → Assignment submissions</span>.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Advanced assignments</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock advanced assignments →</a></div><h3 id="advanced-quiz-types-question-banks" tabindex="-1">Advanced quiz types &amp; question banks <a class="header-anchor" href="#advanced-quiz-types-question-banks" aria-label="Permalink to &quot;Advanced quiz types &amp; question banks&quot;">​</a></h3><p>Reuse questions across many quizzes from a central <strong>Question bank</strong>. Random pools, randomization, advanced types.</p><ul><li><strong>Where:</strong> Course Builder → quiz editor; <span class="screen-path">Course → Content library → Question banks</span>.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Advanced quiz types</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock advanced quizzes →</a></div><h3 id="gradebook" tabindex="-1">Gradebook <a class="header-anchor" href="#gradebook" aria-label="Permalink to &quot;Gradebook&quot;">​</a></h3><p>Per-learner / per-course grade view across quizzes and graded assignments. Export to CSV. Drilldown by quiz / assignment.</p><ul><li><strong>Where:</strong> <span class="screen-path">Grading &amp; submissions → Gradebook</span> + <span class="screen-path">Letter grades &amp; scales</span>.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Gradebook</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock gradebook →</a></div><h3 id="advanced-certificates-builder-qr-verification" tabindex="-1">Advanced certificates (builder, QR, verification) <a class="header-anchor" href="#advanced-certificates-builder-qr-verification" aria-label="Permalink to &quot;Advanced certificates (builder, QR, verification)&quot;">​</a></h3><p>Drag-and-drop certificate builder, more merge fields, QR codes, public verify pages.</p><ul><li><strong>Where:</strong> <span class="screen-path">Sikshya → Certificates → Templates</span> (new builder) and <span class="screen-path">Certificates → Add-on defaults</span>.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Advanced certificates</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock advanced certificates →</a></div><h2 id="sell-revenue-growth" tabindex="-1">Sell (revenue growth) <a class="header-anchor" href="#sell-revenue-growth" aria-label="Permalink to &quot;Sell (revenue growth)&quot;">​</a></h2><h3 id="subscriptions-memberships" tabindex="-1">Subscriptions &amp; memberships <a class="header-anchor" href="#subscriptions-memberships" aria-label="Permalink to &quot;Subscriptions &amp; memberships&quot;">​</a></h3><p>Recurring billing — monthly / yearly plans for member-only academy access.</p><ul><li><strong>Where:</strong> <span class="screen-path">Commerce → Subscriptions</span>; new course type <strong>Subscription only</strong>.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Subscriptions &amp; memberships</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock subscriptions →</a></div><h3 id="advanced-coupons-upsells" tabindex="-1">Advanced coupons &amp; upsells <a class="header-anchor" href="#advanced-coupons-upsells" aria-label="Permalink to &quot;Advanced coupons &amp; upsells&quot;">​</a></h3><p>Minimum cart total, course / category restrictions, &quot;first-time buyer only&quot; rules, stacking guards.</p><ul><li><strong>Where:</strong> <span class="screen-path">Commerce → Coupons</span> — extra fields appear on each coupon.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Advanced coupons</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock advanced coupons →</a></div><h3 id="dynamic-checkout-fields" tabindex="-1">Dynamic checkout fields <a class="header-anchor" href="#dynamic-checkout-fields" aria-label="Permalink to &quot;Dynamic checkout fields&quot;">​</a></h3><p>Configurable checkout questions (text, select, checkbox) with conditional visibility.</p><ul><li><strong>Where:</strong> <span class="screen-path">Settings → Enrollment → Dynamic checkout fields</span>.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Dynamic checkout fields</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock dynamic fields →</a></div><h3 id="social-login" tabindex="-1">Social login <a class="header-anchor" href="#social-login" aria-label="Permalink to &quot;Social login&quot;">​</a></h3><p>Sign-in with Google (and other providers). One click instead of password fatigue.</p><ul><li><strong>Where:</strong> <span class="screen-path">Sikshya → Branding → Social login</span>.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Social login</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock social login →</a></div><h2 id="operate-analytics-reporting-audit" tabindex="-1">Operate (analytics, reporting, audit) <a class="header-anchor" href="#operate-analytics-reporting-audit" aria-label="Permalink to &quot;Operate (analytics, reporting, audit)&quot;">​</a></h2><h3 id="advanced-analytics-exports" tabindex="-1">Advanced analytics &amp; exports <a class="header-anchor" href="#advanced-analytics-exports" aria-label="Permalink to &quot;Advanced analytics &amp; exports&quot;">​</a></h3><p>Detailed enrollment / progress / revenue exports for Excel and Sheets. Includes a learner self-export option.</p><ul><li><strong>Where:</strong> <span class="screen-path">Reports → Overview</span>; admin and learner export buttons.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Advanced analytics &amp; exports</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock advanced analytics →</a></div><h3 id="student-activity-log" tabindex="-1">Student activity log <a class="header-anchor" href="#student-activity-log" aria-label="Permalink to &quot;Student activity log&quot;">​</a></h3><p>Timeline of milestones — enrollment, completions, quiz attempts, submissions, checkout. Configurable retention.</p><ul><li><strong>Where:</strong> <span class="screen-path">Tools → Activity log</span>.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Student activity log</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock the activity log →</a></div><h3 id="enterprise-reporting" tabindex="-1">Enterprise reporting <a class="header-anchor" href="#enterprise-reporting" aria-label="Permalink to &quot;Enterprise reporting&quot;">​</a></h3><p>Weekly KPI rollup emails for inbox-friendly executive snapshots.</p><ul><li><strong>Where:</strong> <span class="screen-path">Reports → Enterprise</span>.</li><li><strong>Plan:</strong> Scale.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Enterprise reporting</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock enterprise reporting →</a></div><h2 id="communicate-email-marketing-automation" tabindex="-1">Communicate (email, marketing, automation) <a class="header-anchor" href="#communicate-email-marketing-automation" aria-label="Permalink to &quot;Communicate (email, marketing, automation)&quot;">​</a></h2><h3 id="professional-email-delivery-branded-templates" tabindex="-1">Professional email delivery &amp; branded templates <a class="header-anchor" href="#professional-email-delivery-branded-templates" aria-label="Permalink to &quot;Professional email delivery &amp; branded templates&quot;">​</a></h3><p>First-class ESP setup (SendGrid-style) plus a branded multi-template kit (header, footer, accent colors, logo).</p><ul><li><strong>Where:</strong> <span class="screen-path">Email → Delivery</span> — extra panels appear.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Professional email delivery &amp; branded templates</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock branded delivery →</a></div><h3 id="email-advanced-customization" tabindex="-1">Email advanced customization <a class="header-anchor" href="#email-advanced-customization" aria-label="Permalink to &quot;Email advanced customization&quot;">​</a></h3><p>Per-template HTML overrides, extra layout slots, conditional content blocks.</p><ul><li><strong>Where:</strong> template editor → extra panels.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Email advanced customization</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock email customization →</a></div><h3 id="crm-email-automation" tabindex="-1">CRM email automation <a class="header-anchor" href="#crm-email-automation" aria-label="Permalink to &quot;CRM email automation&quot;">​</a></h3><p>Trigger sequences (Day 0 → Day 3 → Day 7) on enrollment, completion, abandoned cart.</p><ul><li><strong>Where:</strong> dedicated screen after enabling.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">CRM email automation</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock CRM automation →</a></div><h3 id="email-marketing-mailchimp-mailerlite" tabindex="-1">Email marketing (Mailchimp / MailerLite) <a class="header-anchor" href="#email-marketing-mailchimp-mailerlite" aria-label="Permalink to &quot;Email marketing (Mailchimp / MailerLite)&quot;">​</a></h3><p>Sync enrollments and completions to Mailchimp or MailerLite lists / segments automatically.</p><ul><li><strong>Where:</strong> <span class="screen-path">Integrations → Email marketing</span>.</li><li><strong>Plan:</strong> Growth.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Email marketing</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock email marketing →</a></div><h3 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h3><p>Deliver signed JSON to your HTTPS endpoints whenever LMS events fire (purchase, enrollment, completion, certificate). Build custom backends without polling.</p><ul><li><strong>Where:</strong> <span class="screen-path">Integrations → Webhooks &amp; API</span>.</li><li><strong>Plan:</strong> Scale.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Webhooks</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock webhooks →</a></div><h3 id="zapier" tabindex="-1">Zapier <a class="header-anchor" href="#zapier" aria-label="Permalink to &quot;Zapier&quot;">​</a></h3><p>First-class Zapier triggers and actions. Sikshya events fan out into thousands of Zaps without bespoke code.</p><ul><li><strong>Where:</strong> <span class="screen-path">Integrations → Webhooks &amp; API</span> with the Zapier app.</li><li><strong>Plan:</strong> Scale.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Zapier</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock Zapier →</a></div><h3 id="public-api-api-keys" tabindex="-1">Public API &amp; API keys <a class="header-anchor" href="#public-api-api-keys" aria-label="Permalink to &quot;Public API &amp; API keys&quot;">​</a></h3><p>Issue revocable API keys for partners and bespoke integrations. Scoped permissions over REST.</p><ul><li><strong>Where:</strong> <span class="screen-path">Integrations → API keys</span>.</li><li><strong>Plan:</strong> Scale.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Public API &amp; API keys</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock the public API →</a></div><h2 id="scale-marketplace-branding-enterprise" tabindex="-1">Scale (marketplace, branding, enterprise) <a class="header-anchor" href="#scale-marketplace-branding-enterprise" aria-label="Permalink to &quot;Scale (marketplace, branding, enterprise)&quot;">​</a></h2><h3 id="multi-vendor-marketplace" tabindex="-1">Multi-vendor marketplace <a class="header-anchor" href="#multi-vendor-marketplace" aria-label="Permalink to &quot;Multi-vendor marketplace&quot;">​</a></h3><p>Open the academy to many independent vendors with their own storefronts. Set per-vendor / per-course commission, manage payouts.</p><ul><li><strong>Where:</strong> <span class="screen-path">Commerce → Marketplace</span>.</li><li><strong>Plan:</strong> Scale.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Multi-vendor marketplace</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock the marketplace →</a></div><h3 id="white-label-branding" tabindex="-1">White label &amp; branding <a class="header-anchor" href="#white-label-branding" aria-label="Permalink to &quot;White label &amp; branding&quot;">​</a></h3><p>Replace Sikshya labels in admin and learner UI with your own brand (logo, naming, optional &quot;powered by&quot; toggle).</p><ul><li><strong>Where:</strong> <span class="screen-path">Sikshya → Branding → White label</span>.</li><li><strong>Plan:</strong> Scale.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">White label &amp; branding</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock white label →</a></div><h3 id="multisite-network-license-tools" tabindex="-1">Multisite &amp; network license tools <a class="header-anchor" href="#multisite-network-license-tools" aria-label="Permalink to &quot;Multisite &amp; network license tools&quot;">​</a></h3><p>Manage license slots across many subsites of a WordPress multisite network from one place.</p><ul><li><strong>Where:</strong> Network admin (after multisite is configured).</li><li><strong>Plan:</strong> Scale.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Multisite &amp; network license tools</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock multisite tools →</a></div><h3 id="multilingual-wpml-weglot" tabindex="-1">Multilingual (WPML / Weglot) <a class="header-anchor" href="#multilingual-wpml-weglot" aria-label="Permalink to &quot;Multilingual (WPML / Weglot)&quot;">​</a></h3><p>Bridge Sikshya&#39;s interface strings into WPML / Weglot translation stacks. Multilingual catalogs become a first-class feature.</p><ul><li><strong>Where:</strong> <span class="screen-path">Integrations → Multilingual</span>.</li><li><strong>Plan:</strong> Scale.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Multilingual (WPML / Weglot)</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock multilingual →</a></div><h2 id="manage-your-add-ons" tabindex="-1">Manage your add-ons <a class="header-anchor" href="#manage-your-add-ons" aria-label="Permalink to &quot;Manage your add-ons&quot;">​</a></h2><p>Open <span class="screen-path">Sikshya → Add-ons</span>:</p><ul><li><strong>Search</strong> the catalog by name.</li><li><strong>Filter by category</strong> (course, commerce, learner, communication, analytics, integrations, etc.).</li><li><strong>Tier filter</strong> (Starter / Growth / Scale).</li><li><strong>Sort</strong> by importance, name, tier, or status.</li></ul><p>Each card shows:</p><ul><li>Title, short description, hover <strong>About this add-on</strong> popover.</li><li>Plan badge: <strong>Free</strong>, <strong>Starter</strong>, <strong>Growth</strong>, or <strong>Scale</strong>.</li><li>An on / off toggle. Toggles are <strong>locked</strong> with an &quot;Upgrade&quot; prompt if your plan doesn&#39;t include the add-on.</li></ul><p>Use the <strong>Select visible</strong> + <strong>Enable selected</strong> / <strong>Disable selected</strong> to bulk-manage.</p><blockquote><p>Disabling an add-on hides its UI but <strong>keeps your data</strong>. Re-enable later to bring it back.</p></blockquote><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="/docs/hooks-filters">Hooks &amp; filters</a> — code-level extension points.</li><li><a href="/docs/api-reference">REST API</a> — every endpoint Pro adds.</li><li><a href="/docs/support">Support</a> — how to file a Pro priority ticket.</li></ul>',154)])])}const g=s(r,[["render",o]]);export{h as __pageData,g as default};
